<div class="page-heading"><div><span class="eyebrow">Agendamento #<?=e($appointment['id'])?></span><h1><?=e($appointment['cliente_nome'])?></h1><p><?=e(local_datetime($appointment['inicio_at'],$company['timezone'],'d/m/Y · H:i'))?> até <?=e(local_datetime($appointment['fim_at'],$company['timezone'],'H:i'))?></p></div><a class="button" href="<?=e(url('/dashboard'))?>"><i class="bi bi-arrow-left"></i>Agenda</a></div>
